using System.Text;
using UnityEngine;
using TMPro;
using LWS.TruckSports;
using LWS.TruckBowling;
namespace LWS.TruckCornhole {
public enum CornholeScreen {Setup,Play,Join,Pause,Help,Settings,Result,Confirm}
public sealed class CornholeMenus:SportsMenuView {
 public CornholeMatch match;public TMP_InputField[] names;public TMP_Text[] sources,levels,pads;public GameObject[] rows;public GameObject[] replayButtons;public TMP_Text countText,setupInfo,joinInfo,resultText,confirmText;public RectTransform[] views;public TMP_Text[] headers,footers,indicators;
 public CornholeScreen Screen{get;private set;}bool dirty=true;float nextHUD;int returnPage,helpPage;string confirm;readonly StringBuilder text=new StringBuilder(700);SportsMenuAction[] joinActions;
 public const string Help="THE TRUCK IS THE BAG\nDrive down the ramp into the trampoline. Your speed, position and heading determine the launch. There is no launch button. Learn the reference stripes; try 13\u201314 m/s at the bed. Slow entries undershoot, fast or angled entries can miss.\n\nCONTROLS\nForward accelerates; opposite input brakes before reversing. Left/right steer. Whole controller: left stick steer, RT forward, LT reverse. Shared controller: one truck per left/right stick. Keyboard clusters shown in setup. Esc / assigned Start pauses all courses without losing flight or scores.\n\nAIRBORNE\nLeft/right gives a limited lateral nudge and bank. Release forward/back after launch, then press again for a small range/pitch correction. The budget is shared across directions: you cannot hover or reverse flight. First board contact disables all controls. Landings, skids and collisions are physical.\n\nCAB AND REPLAY\nEvery player starts in the driver seat, with a stable horizon. After a throw settles, REPLAY opens a visual recording. ANGLE cycles cab, chase, board side and overhead; SPEED cycles 0.25x / 0.5x / 1x / 2x / 4x. RESTART rewinds; LIVE CAB returns. Replays affect only your view, never physics or scores. Your next delivery waits while you review (45-second limit); other participants keep playing.\n\nARCADE FREE-FOR-ALL \u00b7 NO CANCELLATION\nFive rounds, four fresh trucks per participant each round. Each participant drives an independent approach to the shared opposing board. Trucks pass through one another during initial flight; native landing contacts enable only when both trucks reach the board and are safely separated. Earlier trucks stay on the board and can be pushed off (lose 1) or through the hole (become 3). Board points remain PROVISIONAL until the round finishes.\n\n1 POINT: stable support on the TOP of the board, no surrounding-ground contact. 3 POINTS: the complete truck passes DOWN through the opening, counted once and collected below. 0: off board, ground contact, side-face hangs or still moving at the generous resolution limit. A truck hanging in the opening only scores 1 if genuinely supported and settled.\n\nApproaches progress independently. After everyone's fourth truck and settling, round points are banked. Highest total after round five wins; equal totals tie. Rematch retains names, input sources and difficulty. No hot seat, networking or powerups.\n\nWEATHER AND WIND\nChoose Random or an installed forecast in setup. The bottom-right arrow shows the direction wind pushes relative to your approach heading; speed is in MPH. The same wind affects horizontal flight continuously. Landed trucks remain physical and receive no wind assistance. Random rolls again on rematch; explicit forecasts persist.";
 static readonly int HelpSplit=Help.IndexOf("ARCADE FREE-FOR-ALL");static readonly string[] HelpPages={Help.Substring(0,HelpSplit),Help.Substring(HelpSplit)};
 public void NextHelp(){helpPage=1-helpPage;HelpText();}
 void HelpText(){pages[4].transform.Find("Rules").GetComponent<TMP_Text>().text=HelpPages[helpPage];pages[4].transform.Find("Title").GetComponent<TMP_Text>().text="CORNHOLE \u00b7 HOW TO PLAY "+(helpPage+1)+" / 2";}
 protected override void Start(){base.Start();joinActions=pages[2].GetComponentsInChildren<SportsMenuAction>(true);for(int i=0;i<4;i++){int slot=i;names[i].onEndEdit.AddListener(value=>{match.setup.players[slot].name=string.IsNullOrWhiteSpace(value)?"Player "+(slot+1):value.Trim();match.Save();});}Show(Screen);}
 public void Dirty(){dirty=true;}
 public void LayoutView(int i,Rect rect,bool enabled){views[i].anchorMin=new Vector2(rect.xMin,rect.yMin);views[i].anchorMax=new Vector2(rect.xMax,rect.yMax);views[i].offsetMin=views[i].offsetMax=Vector2.zero;views[i].gameObject.SetActive(enabled&&Screen==CornholeScreen.Play);}
 public void Show(CornholeScreen screen){Screen=screen;if(screen==CornholeScreen.Help){helpPage=0;HelpText();}base.Show((int)screen);for(int i=0;i<4;i++)views[i].gameObject.SetActive(screen==CornholeScreen.Play&&match.courses[i].chase.view.enabled);if(screen==CornholeScreen.Settings)SettingsText();dirty=true;Refresh();}
 public override void Action(string key){if(match.InMatch&&!match.Finished&&Screen!=CornholeScreen.Play&&!match.MenuConfirm())return;base.Action(key);foreach(var prefix in new[]{"replay","angle","rate","rewind","live"})if(key.StartsWith(prefix)&&int.TryParse(key.Substring(prefix.Length),out var slot)&&slot<match.setup.count){var replay=match.courses[slot].replay;switch(prefix){case "replay":match.ReplayPlay(slot);break;case "angle":replay.NextAngle();break;case "rate":replay.NextSpeed();break;case "rewind":replay.Rewind();break;case "live":match.ReplayStop(slot);break;}return;}if(key.StartsWith("source")){match.CycleSource(int.Parse(key.Substring(6)));return;}if(key.StartsWith("level")){var p=match.setup.players[int.Parse(key.Substring(5))];p.difficulty=(BowlingDifficulty)(((int)p.difficulty+1)%3);match.Save();return;}if(key.StartsWith("pad")){match.NextPad(int.Parse(key.Substring(3)));return;}if(key.StartsWith("reassign")){match.Unassign(int.Parse(key.Substring(8)));return;}
  switch(key){case "review":Show(CornholeScreen.Play);for(int i=0;i<match.setup.count;i++)match.courses[i].replay.Play();break;case "helpnext":NextHelp();break;case "count":match.setup.count=match.setup.count%4+1;match.Save();break;case "allai":match.AllAI();break;case "start":case "rematch":match.StartMatch();break;case "resume":match.Resume();break;case "setup":match.ChangeSetup();break;case "help":returnPage=(int)Screen;Show(CornholeScreen.Help);break;case "settings":returnPage=(int)Screen;Show(CornholeScreen.Settings);break;case "back":Show(Screen==CornholeScreen.Join?CornholeScreen.Setup:(CornholeScreen)returnPage);break;case "restart":case "front":if(match.InMatch&&!match.Finished){confirm=key;confirmText.text=key=="restart"?"Restart all Cornhole courses?\nMatch scores reset; participants are retained.":"Return to sport selection?\nThis Cornhole match will be abandoned.";match.Gate();Show(CornholeScreen.Confirm);}else{match.Save();SportsNavigation.FrontEnd();}break;case "no":Show(CornholeScreen.Pause);break;case "yes":if(confirm=="restart")match.StartMatch();else{match.Save();SportsNavigation.FrontEnd();}break;}
  dirty=true;Refresh();
 }
 void Refresh(){if(!dirty)return;dirty=false;var s=match.setup;if(Screen==CornholeScreen.Setup){countText.text=s.count+" PARTICIPANTS \u00b7 SIMULTANEOUS";for(int i=0;i<4;i++){rows[i].SetActive(i<s.count);var p=s.players[i];names[i].SetTextWithoutNotify(p.name);names[i].textComponent.color=p.color;sources[i].text=p.source==BowlingSource.Keyboard?(p.forward==UnityEngine.InputSystem.Key.UpArrow&&p.left==UnityEngine.InputSystem.Key.LeftArrow&&p.back==UnityEngine.InputSystem.Key.DownArrow&&p.right==UnityEngine.InputSystem.Key.RightArrow?"ARROW KEYS":p.forward+"/"+p.left+"/"+p.back+"/"+p.right):p.source.ToString().ToUpper();sources[i].color=p.color;levels[i].text=p.source==BowlingSource.AI?p.difficulty.ToString().ToUpper():"HUMAN";levels[i].transform.parent.gameObject.SetActive(p.source==BowlingSource.AI);pads[i].transform.parent.gameObject.SetActive(p.Controller);pads[i].text=match.Ready(i)&&p.pad!=null?"PAD #"+p.pad.deviceId:"ASSIGN PAD";}setupInfo.text=s.Validate(out var reason)?"Five rounds \u00d7 four trucks \u00b7 Every course plays independently\nWhole controllers exclusive; left/right stick sources may share one pad. North / Y joins in the device screen.":reason;Focus();}
  if(Screen==CornholeScreen.Join){text.Clear().Append("North / Y / Triangle joins the next unassigned source.\nUse REASSIGN for explicit replacement. Release all controls before resuming.\n\n");for(int i=0;i<s.count;i++){var p=s.players[i];text.Append(p.name).Append(" \u00b7 ").Append(p.source).Append(" \u00b7 ").Append(match.Ready(i)?p.pad!=null?p.pad.displayName+" #"+p.pad.deviceId:"READY":"NOT CONNECTED").Append('\n');}joinInfo.text=text.ToString();if(joinActions!=null)foreach(var a in joinActions){if(a.action.StartsWith("reassign")){int i=int.Parse(a.action.Substring(8));a.gameObject.SetActive(i<s.count&&s.players[i].Controller);}if(a.action=="resume")a.button.GetComponent<UnityEngine.UI.Button>().interactable=match.DevicesReady;}}
  if(Screen==CornholeScreen.Result){text.Clear().Append(match.winners.Length>1?"TIE":"WINNER");foreach(int i in match.winners)text.Append(" \u00b7 ").Append(s.players[i].name);text.Append("\n\n");for(int i=0;i<s.count;i++)text.Append(s.players[i].name).Append("   ").Append(match.totals[i]).Append(" POINTS\n");resultText.text=text.ToString();}
 }
 protected override void Update(){base.Update();Refresh();if(Screen!=CornholeScreen.Play||Time.unscaledTime<nextHUD)return;nextHUD=Time.unscaledTime+.1f;for(int i=0;i<match.setup.count;i++){var c=match.courses[i];text.Clear().Append(c.Owner.name).Append(" \u00b7 ROUND ").Append(match.Round).Append(" / 5 \u00b7 TRUCK ").Append(c.Attempts).Append(" / 4\nBANKED ").Append(match.totals[i]).Append(match.RoundBreak||match.Finished?"     ROUND FINAL +":"     PROVISIONAL +").Append(match.RoundBreak||match.Finished?match.lastRound[i]:c.Provisional);headers[i].text=text.ToString();headers[i].color=c.Owner.color;
   footers[i].text=match.RoundBreak||match.Finished?"ROUND BANKED +"+match.lastRound[i]+" \u00b7 NEXT ROUND SOON":c.Notice+(c.Phase==CornholePhase.Approach?"\nSpeed "+Mathf.Max(0,c.Current.body.linearVelocity.z).ToString("F1")+" m/s \u00b7 try 13\u201314 at bed \u00b7 reverse brakes":c.Phase==CornholePhase.Flight?"\nLeft/right nudges \u00b7 release then press forward/back \u00b7 budget "+Mathf.RoundToInt(100*(1-c.Current.UsedAftertouch/c.aftertouchBudget))+"%":"\nBoard points can still change until the round ends");
   var replay=c.replay;for(int b=0;b<5;b++){bool show=replay.Playing||b==4&&match.Finished||b==0&&replay.Available&&(c.Phase==CornholePhase.AttemptResult||c.Phase==CornholePhase.Waiting)&&!match.RoundBreak;replayButtons[i*5+b].SetActive(show);}if(replay.Playing)footers[i].text="REPLAY "+replay.AngleName+" "+replay.Speed.ToString("0.##")+"x "+replay.Clock.ToString("F1")+" / "+replay.Duration.ToString("F1")+"s\nVisual recording only \u00b7 other courses continue \u00b7 LIVE CAB to return";
   var p=c.chase.view.WorldToViewportPoint(c.board.position);bool outside=p.z<0||p.x<.08f||p.x>.92f||p.y<.15f||p.y>.82f;indicators[i].gameObject.SetActive(c.Phase==CornholePhase.Flight&&outside);if(outside){if(p.z<0){p.x=1-p.x;p.y=1-p.y;}var r=indicators[i].rectTransform;r.anchorMin=r.anchorMax=new Vector2(Mathf.Clamp(p.x,.16f,.84f),Mathf.Clamp(p.y,.25f,.75f));r.anchoredPosition=Vector2.zero;indicators[i].text="TARGET BOARD "+Mathf.RoundToInt(Vector3.Distance(c.Current.body.position,c.board.position))+"m";}
  }}
}
}